//! Permission and authorization layer
//!
//! This module handles authentication and authorization for all API operations.
//! It provides fine-grained control over what operations each session can execute.

use super::{error::ApiError, session::SessionContext};
use serde::{Deserialize, Serialize};
use specta::Type;
use std::collections::HashMap;
use thiserror::Error;
use uuid::Uuid;

pub use super::session::AuthLevel;

/// Permission checking and enforcement
#[derive(Clone)]
pub struct PermissionLayer {
	/// Permission policies and rules
	policies: PermissionPolicies,
}

/// Permission policies configuration
#[derive(Debug, Clone)]
pub struct PermissionPolicies {
	/// Whether to enforce permissions (can disable for development)
	pub enforce: bool,

	/// Default permissions for device-level access
	pub device_defaults: PermissionSet,

	/// Library-specific permission overrides
	pub library_overrides: HashMap<Uuid, LibraryPermissions>,
}

/// Complete permission set for a session
#[derive(Debug, Clone, Serialize, Deserialize, Type)]
pub struct PermissionSet {
	/// Core system permissions
	pub core: CorePermissions,

	/// Library operation permissions
	pub library: LibraryPermissions,

	/// Network operation permissions
	pub network: NetworkPermissions,

	/// Job management permissions
	pub jobs: JobPermissions,
}

/// Core system permissions
#[derive(Debug, Clone, Serialize, Deserialize, Type)]
pub struct CorePermissions {
	pub can_read_status: bool,
	pub can_manage_libraries: bool,
	pub can_modify_settings: bool,
	pub can_manage_devices: bool,
}

/// Library operation permissions
#[derive(Debug, Clone, Serialize, Deserialize, Type)]
pub struct LibraryPermissions {
	pub can_read: bool,
	pub can_write: bool,
	pub can_delete: bool,
	pub can_manage_locations: bool,
	pub can_manage_tags: bool,
	pub can_search: bool,
	pub can_index: bool,
}

/// Network operation permissions
#[derive(Debug, Clone, Serialize, Deserialize, Type)]
pub struct NetworkPermissions {
	pub can_start_stop: bool,
	pub can_pair_devices: bool,
	pub can_send_spacedrop: bool,
	pub can_manage_devices: bool,
}

/// Job management permissions
#[derive(Debug, Clone, Serialize, Deserialize, Type)]
pub struct JobPermissions {
	pub can_list: bool,
	pub can_pause_resume: bool,
	pub can_cancel: bool,
	pub can_view_details: bool,
}

/// Permission-related errors
#[derive(Debug, Error, Serialize, Deserialize, Type)]
pub enum PermissionError {
	#[error("Authentication required")]
	Unauthenticated,

	#[error("Insufficient privileges for this operation")]
	InsufficientPrivileges,

	#[error("Library access denied: {library_id}")]
	LibraryAccessDenied { library_id: Uuid },

	#[error("Operation not allowed: {operation}")]
	OperationNotAllowed { operation: String },

	#[error("Rate limit exceeded")]
	RateLimitExceeded,
}

impl PermissionLayer {
	/// Create a new permission layer with default policies
	pub fn new() -> Self {
		Self {
			policies: PermissionPolicies {
				enforce: true,
				device_defaults: PermissionSet::device_default(),
				library_overrides: HashMap::new(),
			},
		}
	}

	/// Create a permissive layer for development
	pub fn permissive() -> Self {
		Self {
			policies: PermissionPolicies {
				enforce: false,
				device_defaults: PermissionSet::admin_all(),
				library_overrides: HashMap::new(),
			},
		}
	}

	/// Check if session can execute a library action
	pub async fn check_library_action<A>(
		&self,
		session: &SessionContext,
		_action_type: std::marker::PhantomData<A>,
	) -> Result<(), PermissionError>
	where
		A: crate::infra::action::LibraryAction,
	{
		if !self.policies.enforce {
			return Ok(());
		}

		// Check basic authentication
		if session.auth.authentication_level == AuthLevel::None {
			return Err(PermissionError::Unauthenticated);
		}

		// Check library access
		if session.current_library_id.is_none() {
			return Err(PermissionError::OperationNotAllowed {
				operation: "Library action requires library context".to_string(),
			});
		}

		// Check library permissions
		if !session.permissions.library.can_write {
			return Err(PermissionError::InsufficientPrivileges);
		}

		// Future: More fine-grained checks based on action type
		// match std::any::type_name::<A>() {
		//     "FileCopyAction" => check_file_permissions(),
		//     "IndexingAction" => check_indexing_permissions(),
		//     _ => Ok(()),
		// }

		Ok(())
	}

	/// Check if session can execute a core action
	pub async fn check_core_action<A>(
		&self,
		session: &SessionContext,
		_action_type: std::marker::PhantomData<A>,
	) -> Result<(), PermissionError>
	where
		A: crate::infra::action::CoreAction,
	{
		if !self.policies.enforce {
			return Ok(());
		}

		// Core actions typically need higher privileges
		match session.auth.authentication_level {
			AuthLevel::Device | AuthLevel::User(_) | AuthLevel::Admin(_) => {
				if session.permissions.core.can_manage_libraries {
					Ok(())
				} else {
					Err(PermissionError::InsufficientPrivileges)
				}
			}
			AuthLevel::None => Err(PermissionError::Unauthenticated),
		}
	}

	/// Check if session can execute a library query
	pub async fn check_library_query<Q>(
		&self,
		session: &SessionContext,
		_query_type: std::marker::PhantomData<Q>,
	) -> Result<(), PermissionError>
	where
		Q: crate::infra::query::LibraryQuery,
	{
		if !self.policies.enforce {
			return Ok(());
		}

		// Queries typically need read permissions
		if session.auth.authentication_level == AuthLevel::None {
			return Err(PermissionError::Unauthenticated);
		}

		if !session.permissions.library.can_read {
			return Err(PermissionError::InsufficientPrivileges);
		}

		Ok(())
	}

	/// Check if session can execute a core query
	pub async fn check_core_query<Q>(
		&self,
		session: &SessionContext,
		_query_type: std::marker::PhantomData<Q>,
	) -> Result<(), PermissionError>
	where
		Q: crate::infra::query::CoreQuery,
	{
		if !self.policies.enforce {
			return Ok(());
		}

		// Core queries need basic authentication
		if session.auth.authentication_level == AuthLevel::None {
			return Err(PermissionError::Unauthenticated);
		}

		if !session.permissions.core.can_read_status {
			return Err(PermissionError::InsufficientPrivileges);
		}

		Ok(())
	}
}

impl PermissionSet {
	/// Full admin permissions
	pub fn admin_all() -> Self {
		Self {
			core: CorePermissions {
				can_read_status: true,
				can_manage_libraries: true,
				can_modify_settings: true,
				can_manage_devices: true,
			},
			library: LibraryPermissions {
				can_read: true,
				can_write: true,
				can_delete: true,
				can_manage_locations: true,
				can_manage_tags: true,
				can_search: true,
				can_index: true,
			},
			network: NetworkPermissions {
				can_start_stop: true,
				can_pair_devices: true,
				can_send_spacedrop: true,
				can_manage_devices: true,
			},
			jobs: JobPermissions {
				can_list: true,
				can_pause_resume: true,
				can_cancel: true,
				can_view_details: true,
			},
		}
	}

	/// Default device permissions (current behavior)
	pub fn device_default() -> Self {
		Self::admin_all() // For now, maintain current permissive behavior
	}

	/// Read-only permissions
	pub fn read_only() -> Self {
		Self {
			core: CorePermissions {
				can_read_status: true,
				can_manage_libraries: false,
				can_modify_settings: false,
				can_manage_devices: false,
			},
			library: LibraryPermissions {
				can_read: true,
				can_write: false,
				can_delete: false,
				can_manage_locations: false,
				can_manage_tags: false,
				can_search: true,
				can_index: false,
			},
			network: NetworkPermissions {
				can_start_stop: false,
				can_pair_devices: false,
				can_send_spacedrop: false,
				can_manage_devices: false,
			},
			jobs: JobPermissions {
				can_list: true,
				can_pause_resume: false,
				can_cancel: false,
				can_view_details: true,
			},
		}
	}
}

/// Convert permission errors to API errors
impl From<PermissionError> for ApiError {
	fn from(err: PermissionError) -> Self {
		match err {
			PermissionError::Unauthenticated => Self::Unauthenticated,
			PermissionError::InsufficientPrivileges => Self::InsufficientPermissions {
				reason: "Operation not allowed".to_string(),
			},
			PermissionError::LibraryAccessDenied { library_id } => Self::LibraryNotFound {
				library_id: library_id.to_string(),
			},
			PermissionError::OperationNotAllowed { operation } => {
				Self::InsufficientPermissions { reason: operation }
			}
			PermissionError::RateLimitExceeded => Self::RateLimitExceeded {
				retry_after_seconds: 60,
			},
		}
	}
}

//! Permission and security system for WASM extensions

use serde::{Deserialize, Serialize};
use std::collections::HashMap;
use std::sync::Arc;
use std::time::{Duration, Instant};
use thiserror::Error;
use tokio::sync::RwLock;
use uuid::Uuid;

use super::types::ManifestPermissions;

#[derive(Error, Debug)]
pub enum PermissionError {
	#[error("Extension not authorized: {0}")]
	Unauthorized(String),

	#[error("Method not allowed: {0}")]
	MethodNotAllowed(String),

	#[error("Library access denied: {0}")]
	LibraryAccessDenied(String),

	#[error("Rate limit exceeded: {0}")]
	RateLimitExceeded(String),
}

/// Runtime permission checker with rate limiting
#[derive(Clone)]
pub struct ExtensionPermissions {
	extension_id: String,

	/// Methods this extension can call (prefix matching)
	allowed_methods: Vec<String>,

	/// Libraries this extension can access ("*" or specific UUIDs)
	allowed_libraries: Vec<String>,

	/// Rate limiting state
	rate_limiter: Arc<RwLock<RateLimiter>>,

	/// Resource limits
	pub max_memory_mb: usize,
	pub max_concurrent_jobs: usize,
}

struct RateLimiter {
	requests_per_minute: usize,
	recent_requests: Vec<Instant>,
}

impl ExtensionPermissions {
	/// Create permissions from manifest
	pub fn from_manifest(extension_id: String, manifest_perms: &ManifestPermissions) -> Self {
		Self {
			extension_id,
			allowed_methods: manifest_perms.methods.clone(),
			allowed_libraries: manifest_perms.libraries.clone(),
			rate_limiter: Arc::new(RwLock::new(RateLimiter {
				requests_per_minute: manifest_perms.rate_limits.requests_per_minute,
				recent_requests: Vec::new(),
			})),
			max_memory_mb: manifest_perms.max_memory_mb,
			max_concurrent_jobs: manifest_perms.rate_limits.concurrent_jobs,
		}
	}

	/// Check if extension can call this Wire method
	pub fn can_call(&self, method: &str) -> bool {
		// Check if any allowed prefix matches
		self.allowed_methods
			.iter()
			.any(|prefix| method.starts_with(prefix))
	}

	/// Check if extension can access this library
	pub fn can_access_library(&self, library_id: Uuid) -> bool {
		// "*" means all libraries
		if self.allowed_libraries.iter().any(|id| id == "*") {
			return true;
		}

		// Check if specific library UUID is allowed
		self.allowed_libraries
			.iter()
			.any(|id| id.parse::<Uuid>().ok() == Some(library_id))
	}

	/// Check rate limit and record request
	pub async fn check_rate_limit(&self) -> Result<(), PermissionError> {
		let mut limiter = self.rate_limiter.write().await;

		let now = Instant::now();
		let one_minute_ago = now - Duration::from_secs(60);

		// Remove requests older than 1 minute
		limiter
			.recent_requests
			.retain(|&timestamp| timestamp > one_minute_ago);

		// Check if under limit
		if limiter.recent_requests.len() >= limiter.requests_per_minute {
			return Err(PermissionError::RateLimitExceeded(format!(
				"Extension {} exceeded {} requests/minute",
				self.extension_id, limiter.requests_per_minute
			)));
		}

		// Record this request
		limiter.recent_requests.push(now);

		Ok(())
	}

	/// Full permission check for a Wire operation
	pub async fn authorize(
		&self,
		method: &str,
		library_id: Option<Uuid>,
	) -> Result<(), PermissionError> {
		// Check method permission
		if !self.can_call(method) {
			return Err(PermissionError::MethodNotAllowed(format!(
				"Extension {} not allowed to call {}",
				self.extension_id, method
			)));
		}

		// Check library access if specified
		if let Some(lib_id) = library_id {
			if !self.can_access_library(lib_id) {
				return Err(PermissionError::LibraryAccessDenied(format!(
					"Extension {} cannot access library {}",
					self.extension_id, lib_id
				)));
			}
		}

		// Check rate limit
		self.check_rate_limit().await?;

		Ok(())
	}
}

#[cfg(test)]
mod tests {
	use super::*;

	#[test]
	fn test_method_permission() {
		let perms = ExtensionPermissions {
			extension_id: "test".to_string(),
			allowed_methods: vec!["vdfs.".to_string(), "ai.ocr".to_string()],
			allowed_libraries: vec!["*".to_string()],
			rate_limiter: Arc::new(RwLock::new(RateLimiter {
				requests_per_minute: 1000,
				recent_requests: Vec::new(),
			})),
			max_memory_mb: 512,
			max_concurrent_jobs: 10,
		};

		assert!(perms.can_call("vdfs.create_entry"));
		assert!(perms.can_call("vdfs.write_sidecar"));
		assert!(perms.can_call("ai.ocr"));
		assert!(!perms.can_call("credentials.delete")); // Not allowed
	}

	#[test]
	fn test_library_permission() {
		let lib_id = Uuid::new_v4();

		let perms_all = ExtensionPermissions {
			extension_id: "test".to_string(),
			allowed_methods: vec![],
			allowed_libraries: vec!["*".to_string()],
			rate_limiter: Arc::new(RwLock::new(RateLimiter {
				requests_per_minute: 1000,
				recent_requests: Vec::new(),
			})),
			max_memory_mb: 512,
			max_concurrent_jobs: 10,
		};

		assert!(perms_all.can_access_library(lib_id));

		let perms_specific = ExtensionPermissions {
			extension_id: "test".to_string(),
			allowed_methods: vec![],
			allowed_libraries: vec![lib_id.to_string()],
			rate_limiter: Arc::new(RwLock::new(RateLimiter {
				requests_per_minute: 1000,
				recent_requests: Vec::new(),
			})),
			max_memory_mb: 512,
			max_concurrent_jobs: 10,
		};

		assert!(perms_specific.can_access_library(lib_id));
		assert!(!perms_specific.can_access_library(Uuid::new_v4()));
	}
}

import { execFile } from 'child_process';
import { mkdtemp, rm, writeFile } from 'fs/promises';
import { tmpdir } from 'os';
import { join } from 'path';
import { afterEach, describe, expect, it } from 'vitest';
import { cloneRepo } from '../src/git.ts';

function runGit(args: string[], env: NodeJS.ProcessEnv): Promise<string> {
  return new Promise((resolve, reject) => {
    execFile('git', args, { env, encoding: 'utf8' }, (error, stdout) => {
      if (error) reject(error);
      else resolve(stdout);
    });
  });
}

describe('cloneRepo transport allowlist', () => {
  const tempDirs: string[] = [];
  const originalEnv = {
    GIT_ALLOW_PROTOCOL: process.env.GIT_ALLOW_PROTOCOL,
    GIT_CONFIG_GLOBAL: process.env.GIT_CONFIG_GLOBAL,
    GIT_CONFIG_NOSYSTEM: process.env.GIT_CONFIG_NOSYSTEM,
  };

  afterEach(async () => {
    for (const [key, value] of Object.entries(originalEnv)) {
      if (value === undefined) delete process.env[key];
      else process.env[key] = value;
    }
    await Promise.all(tempDirs.splice(0).map((dir) => rm(dir, { recursive: true, force: true })));
  });

  it('overrides inherited allowances for command-capable transports', async () => {
    const root = await mkdtemp(join(tmpdir(), 'skills-transport-test-'));
    tempDirs.push(root);
    const globalConfig = join(root, 'global.gitconfig');

    await writeFile(
      globalConfig,
      '[protocol "skills-test"]\n  allow = always\n[protocol "fd"]\n  allow = always\n'
    );

    process.env.GIT_CONFIG_GLOBAL = globalConfig;
    process.env.GIT_CONFIG_NOSYSTEM = '1';

    const configuredAllowance = await runGit(
      ['config', '--global', '--get', 'protocol.skills-test.allow'],
      process.env
    );
    expect(configuredAllowance.trim()).toBe('always');

    // Make sure user's env doesn't bypass our allow list
    process.env.GIT_ALLOW_PROTOCOL = 'skills-test:ext:fd';
    await expect(cloneRepo('skills-test::fixture')).rejects.toThrow(/transport .* not allowed/i);
    await expect(cloneRepo('ext::git-remote-skills-test')).rejects.toThrow(
      'Unsupported Git transport: ext'
    );
    await expect(cloneRepo('fd::3')).rejects.toThrow(/transport .* not allowed/i);
  });
});

import type { PermissionContext, PermissionRule } from '@agentscope-ai/agentscope/permission';
import { Ban, CircleHelp, FolderOpen, ShieldCheck, ShieldX } from 'lucide-react';
import { useEffect, useRef, useState } from 'react';

import { PanelEmpty } from '@/components/panel/PanelEmpty';
import { Badge } from '@/components/ui/badge';
import { Tooltip, TooltipContent, TooltipTrigger } from '@/components/ui/tooltip';
import { useTranslation } from '@/i18n/useI18n';

/** The behavior keys we render sections for (excludes ``passthrough``). */
type RuleBehavior = 'allow' | 'deny' | 'ask';

interface PermissionPanelProps {
	/**
	 * The permission context to render. Pass ``null`` when no data is
	 * available yet (renders an empty state).
	 */
	permissionContext: PermissionContext | null;
}

/** i18n key suffix for each behavior group title. */
const BEHAVIOR_META: Record<RuleBehavior, { i18nKey: string; icon: typeof ShieldCheck }> = {
	allow: { i18nKey: 'panel.permission.allow', icon: ShieldCheck },
	deny: { i18nKey: 'panel.permission.deny', icon: Ban },
	ask: { i18nKey: 'panel.permission.ask', icon: CircleHelp },
};

/**
 * A monospace value (a path or rule pattern) that truncates to fit its
 * row. When (and only when) the text is actually clipped, hovering
 * reveals the full value in a tooltip anchored to the left.
 *
 * @param value - The text to display.
 * @returns The truncating value element, with a tooltip when clipped.
 */
function TruncatedCode({ value }: { value: string }) {
	const ref = useRef<HTMLSpanElement>(null);
	const [truncated, setTruncated] = useState(false);

	useEffect(() => {
		const el = ref.current;
		if (!el) return;
		const check = () => setTruncated(el.scrollWidth > el.clientWidth);
		check();
		const observer = new ResizeObserver(check);
		observer.observe(el);
		return () => observer.disconnect();
	}, [value]);

	return (
		<Tooltip>
			<TooltipTrigger asChild>
				<span ref={ref} className="min-w-0 flex-1 truncate text-left font-mono text-xs">
					{value}
				</span>
			</TooltipTrigger>
			{truncated ? (
				<TooltipContent side="left" className="max-w-sm font-mono break-all">
					{value}
				</TooltipContent>
			) : null}
		</Tooltip>
	);
}

/**
 * A single tool's rule card: a header naming the tool plus one row per
 * matching rule (pattern on the left, source on the right).
 *
 * @param toolName - The tool these rules apply to.
 * @param rules - The rules configured for this tool under one behavior.
 * @returns The tool card element.
 */
function ToolRuleCard({ toolName, rules }: { toolName: string; rules: PermissionRule[] }) {
	const { t } = useTranslation();
	return (
		<div className="rounded-md border">
			<div className="flex items-center gap-x-2 border-b px-2 py-1.5 text-sm font-medium">
				{toolName}
				<Badge variant="secondary" className="ml-auto">
					{rules.length}
				</Badge>
			</div>
			<ul className="flex flex-col">
				{rules.map((rule, index) => (
					<li
						key={`${rule.rule_content ?? '*'}-${index}`}
						className="flex items-center justify-between gap-x-2 px-2 py-1.5 text-xs not-last:border-b"
					>
						{rule.rule_content ? (
							<TruncatedCode value={rule.rule_content} />
						) : (
							<span className="min-w-0 flex-1 text-muted-foreground">
								{t('panel.permission.anyInvocation')}
							</span>
						)}
						<Badge variant="outline" className="shrink-0">
							{rule.source}
						</Badge>
					</li>
				))}
			</ul>
		</div>
	);
}

/**
 * One behavior group (allow / deny / ask): a titled section that lists
 * a {@link ToolRuleCard} per tool that has rules under this behavior.
 *
 * @param behavior - The behavior category for this section.
 * @param ruleMap - Rules keyed by tool name for this behavior.
 * @returns The section element, or ``null`` when there are no rules.
 */
function BehaviorGroup({
	behavior,
	ruleMap,
}: {
	behavior: RuleBehavior;
	ruleMap: Record<string, PermissionRule[]> | undefined;
}) {
	const { t } = useTranslation();
	const entries = Object.entries(ruleMap ?? {}).filter(([, rules]) => rules.length > 0);
	if (entries.length === 0) return null;

	const meta = BEHAVIOR_META[behavior];
	const Icon = meta.icon;

	return (
		<div className="flex flex-col gap-y-1.5">
			<div className="flex items-center gap-x-1.5 text-xs font-medium text-muted-foreground">
				<Icon className="size-3.5" />
				{t(meta.i18nKey)}
			</div>
			{entries.map(([toolName, rules]) => (
				<ToolRuleCard key={toolName} toolName={toolName} rules={rules} />
			))}
		</div>
	);
}

/**
 * Pure content body for the Permission dock panel. Shows the active
 * permission mode, the working directories in scope, and the configured
 * rules grouped by behavior (deny / ask / allow) and then by tool. Data
 * arrives via props so it owns no data fetching.
 *
 * Renders without its own header/border — the surrounding `Panel`
 * chrome (from `PanelDock`) provides those.
 *
 * @param permissionContext - The permission context, or ``null``.
 * @returns The permission panel body.
 */
export function PermissionPanel({ permissionContext }: PermissionPanelProps) {
	const { t } = useTranslation();
	const workingDirs = Object.values(permissionContext?.working_directories ?? {});
	const hasRules =
		Object.keys(permissionContext?.allow_rules ?? {}).length > 0 ||
		Object.keys(permissionContext?.deny_rules ?? {}).length > 0 ||
		Object.keys(permissionContext?.ask_rules ?? {}).length > 0;

	return (
		<div className="flex flex-col flex-1 min-h-0 gap-y-3">
			<span className="text-muted-foreground text-sm">
				{t('panel.permission.description')}
			</span>

			<div className="flex flex-col flex-1 min-h-0 overflow-y-auto gap-y-4">
				{/* Working directories — always shown, with an empty state. */}
				<div className="flex flex-col gap-y-1.5">
					<div className="flex items-center gap-x-1.5 text-xs font-medium text-muted-foreground">
						<FolderOpen className="size-3.5" />
						{t('panel.permission.workingDirectories')}
					</div>
					{workingDirs.length === 0 ? (
						<p className="text-muted-foreground text-xs px-1 py-2">
							{t('panel.permission.noWorkingDirectories')}
						</p>
					) : (
						<ul className="flex flex-col rounded-md border">
							{workingDirs.map((dir) => (
								<li
									key={dir.path}
									className="flex items-center justify-between gap-x-2 px-2 py-1.5 text-xs not-last:border-b"
								>
