// agent_dom_policy.ts — Agent DOM 操作权限守卫
// 防止 Agent 操作浏览器内部页面或其他受限 URL

/**
 * 敏感 URL 前缀黑名单。
 * 初始只包含浏览器内部协议，为后续扩展（如金融域名）预留位置。
 *
 * 格式：每个条目为字符串前缀，会对 URL 做 startsWith 匹配（大小写不敏感）。
 */
export const SENSITIVE_HOST_PATTERNS: readonly string[] = [
  // 浏览器内部页面
  "chrome://",
  "chrome-extension://",
  "edge://",
  "about:",
  "devtools://",
  "view-source:",
  // 预留位置：如需添加敏感金融/支付域名，可在此追加
];

/**
 * 断言给定 URL 允许被 Agent DOM 操作访问。
 * 不合规则时抛出 Error，由调用方统一向 Agent 报错。
 *
 * @param url 要校验的目标 URL（navigate 传入的字符串，或 tab.url）
 * @throws {Error} 若 URL 匹配黑名单或为空
 */
export function assertDomUrlAllowed(url: string): void {
  // 空字符串拒绝（无法判断目标，安全起见拒绝）
  if (!url) {
    throw new Error("Agent DOM operation not allowed for URL: (empty)");
  }

  // about:blank 是用户刚打开的新标签页，允许
  if (url === "about:blank") {
    return;
  }

  const lower = url.toLowerCase();
  for (const pattern of SENSITIVE_HOST_PATTERNS) {
    if (lower.startsWith(pattern.toLowerCase())) {
      throw new Error(`Agent DOM operation not allowed for URL: ${url}`);
    }
  }
}

package com.vesper.flipper.domain.model

import kotlinx.serialization.SerialName
import kotlinx.serialization.Serializable
import java.util.UUID

/**
 * Scoped permission for path-based access control.
 * Permissions are time-limited and explicitly granted.
 */
@Serializable
data class Permission(
    val id: String = UUID.randomUUID().toString(),
    @SerialName("path_pattern")
    val pathPattern: String,
    @SerialName("allowed_actions")
    val allowedActions: Set<CommandAction>,
    @SerialName("granted_at")
    val grantedAt: Long = System.currentTimeMillis(),
    @SerialName("expires_at")
    val expiresAt: Long,
    @SerialName("granted_by")
    val grantedBy: String = "user",
    val active: Boolean = true
) {
    fun isExpired(): Boolean = System.currentTimeMillis() > expiresAt

    fun isValid(): Boolean = active && !isExpired()

    fun matches(path: String, action: CommandAction): Boolean {
        if (!isValid()) return false
        if (action !in allowedActions) return false
        return matchesPath(path)
    }

    private fun matchesPath(path: String): Boolean {
        // Support glob-style patterns
        val regex = pathPattern
            .replace(".", "\\.")
            .replace("*", ".*")
            .replace("?", ".")
            .toRegex()
        return regex.matches(path)
    }

    fun remainingTimeMs(): Long {
        return (expiresAt - System.currentTimeMillis()).coerceAtLeast(0)
    }

    companion object {
        const val DURATION_5_MINUTES = 5 * 60 * 1000L
        const val DURATION_15_MINUTES = 15 * 60 * 1000L
        const val DURATION_1_HOUR = 60 * 60 * 1000L
        const val DURATION_SESSION = 24 * 60 * 60 * 1000L

        fun createForPath(
            path: String,
            actions: Set<CommandAction>,
            duration: Long = DURATION_15_MINUTES
        ): Permission {
            return Permission(
                pathPattern = path,
                allowedActions = actions,
                expiresAt = System.currentTimeMillis() + duration
            )
        }

        fun createProjectScope(projectPath: String): Permission {
            return Permission(
                pathPattern = "$projectPath/*",
                allowedActions = setOf(
                    CommandAction.LIST_DIRECTORY,
                    CommandAction.READ_FILE,
                    CommandAction.WRITE_FILE,
                    CommandAction.CREATE_DIRECTORY
                ),
                expiresAt = System.currentTimeMillis() + DURATION_SESSION
            )
        }
    }
}

/**
 * Permission request shown to user
 */
data class PermissionRequest(
    val id: String = UUID.randomUUID().toString(),
    val path: String,
    val action: CommandAction,
    val justification: String,
    val suggestedDuration: Long = Permission.DURATION_15_MINUTES,
    val timestamp: Long = System.currentTimeMillis()
)

/**
 * Pending action waiting for user approval
 */
data class PendingApproval(
    val id: String = UUID.randomUUID().toString(),
    val command: ExecuteCommand,
    val riskAssessment: RiskAssessment,
    val diff: FileDiff? = null,
    val traceId: String? = null,
    val timestamp: Long = System.currentTimeMillis(),
    val expiresAt: Long = System.currentTimeMillis() + 5 * 60 * 1000 // 5 min expiry
)

package com.vesper.flipper.domain.service

import com.vesper.flipper.domain.model.CommandAction
import com.vesper.flipper.domain.model.Permission
import com.vesper.flipper.domain.model.PermissionRequest
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import java.util.concurrent.ConcurrentHashMap
import javax.inject.Inject
import javax.inject.Singleton

/**
 * Manages path-based permissions for file operations.
 * Permissions are scoped, time-limited, and explicitly granted.
 */
@Singleton
class PermissionService @Inject constructor() {

    private val permissions = ConcurrentHashMap<String, Permission>()
    private val unlockedProtectedPaths = ConcurrentHashMap<String, Long>()
    private val pendingRequests = ConcurrentHashMap<String, PermissionRequest>()

    private val _activePermissions = MutableStateFlow<List<Permission>>(emptyList())
    val activePermissions: StateFlow<List<Permission>> = _activePermissions.asStateFlow()

    private val _pendingRequest = MutableStateFlow<PermissionRequest?>(null)
    val pendingRequest: StateFlow<PermissionRequest?> = _pendingRequest.asStateFlow()

    /**
     * Check if an action on a path is permitted
     */
    fun hasPermission(path: String, action: CommandAction): Boolean {
        cleanupExpired()
        return permissions.values.any { it.matches(path, action) }
    }

    /**
     * Grant a permission
     */
    fun grantPermission(permission: Permission) {
        permissions[permission.id] = permission
        updateActivePermissions()
    }

    /**
     * Grant permission for a specific path and actions
     */
    fun grantPathPermission(
        path: String,
        actions: Set<CommandAction>,
        duration: Long = Permission.DURATION_15_MINUTES
    ): Permission {
        val permission = Permission.createForPath(path, actions, duration)
        grantPermission(permission)
        return permission
    }

    /**
     * Grant project scope permission
     */
    fun grantProjectScope(projectPath: String): Permission {
        val permission = Permission.createProjectScope(projectPath)
        grantPermission(permission)
        return permission
    }

    /**
     * Revoke a permission by ID
     */
    fun revokePermission(permissionId: String): Boolean {
        val removed = permissions.remove(permissionId) != null
        if (removed) updateActivePermissions()
        return removed
    }

    /**
     * Revoke all permissions for a path pattern
     */
    fun revokePathPermissions(pathPattern: String) {
        permissions.entries.removeIf { it.value.pathPattern == pathPattern }
        updateActivePermissions()
    }

    /**
     * Revoke all permissions
     */
    fun revokeAll() {
        permissions.clear()
        unlockedProtectedPaths.clear()
        updateActivePermissions()
    }

    /**
     * Check if a protected path has been unlocked in settings
     */
    fun isProtectedPathUnlocked(path: String): Boolean {
        val expiry = unlockedProtectedPaths[path] ?: return false
        if (System.currentTimeMillis() > expiry) {
            unlockedProtectedPaths.remove(path)
            return false
        }
        return true
    }

    /**
     * Unlock a protected path (from settings)
     */
    fun unlockProtectedPath(path: String, duration: Long = Permission.DURATION_1_HOUR) {
        unlockedProtectedPaths[path] = System.currentTimeMillis() + duration
    }

    /**
     * Lock a protected path
     */
    fun lockProtectedPath(path: String) {
        unlockedProtectedPaths.remove(path)
    }

    /**
     * Get all active (non-expired) permissions
     */
    fun getActivePermissions(): List<Permission> {
        cleanupExpired()
        return permissions.values.filter { it.isValid() }.toList()
    }

    /**
     * Request permission (queues for user approval)
     */
    fun requestPermission(request: PermissionRequest) {
        pendingRequests[request.id] = request
        _pendingRequest.value = request
    }

    /**
     * Approve a pending permission request
     */
    fun approveRequest(requestId: String, duration: Long = Permission.DURATION_15_MINUTES): Permission? {
        val request = pendingRequests.remove(requestId) ?: return null
        if (_pendingRequest.value?.id == requestId) {
            _pendingRequest.value = null
        }

        val permission = Permission.createForPath(
            request.path,
            setOf(request.action),
            duration
        )
        grantPermission(permission)
        return permission
    }

    /**
     * Deny a pending permission request
     */
    fun denyRequest(requestId: String) {
        pendingRequests.remove(requestId)
        if (_pendingRequest.value?.id == requestId) {
            _pendingRequest.value = null
        }
    }

    private fun cleanupExpired() {
        val now = System.currentTimeMillis()
        permissions.entries.removeIf { !it.value.isValid() }
        unlockedProtectedPaths.entries.removeIf { it.value < now }
    }

    private fun updateActivePermissions() {
        _activePermissions.value = getActivePermissions()
    }
}

from __future__ import annotations
import os
import sys
import select
from typing import Literal, TYPE_CHECKING
from .tool import Tool

if TYPE_CHECKING:
    from tui.keylistener import EscListener
    from features.sandbox.manager import SandboxManager
    from features.plan import PlanModeManager

PermissionBehavior = Literal["allow", "deny"]

# Tools allowed in plan mode (read-only + plan file writes + agent tools)
_PLAN_MODE_ALLOWED_TOOLS = {
    "Read", "Glob", "Grep", "AskUserQuestion",
    "EnterPlanMode", "ExitPlanMode",
    "Agent", "SendMessage", "TaskStop",
}
_PLAN_MODE_WRITE_TOOLS = {"Edit", "Write"}  # allowed only for plan file


class PermissionChecker:
    """Read-only tools are auto-allowed. Bash/writes prompt the user (y/n/always)."""

    def __init__(
        self,
        auto_approve: bool = False,
        sandbox_manager: SandboxManager | None = None,
    ):
        self._auto_approve = auto_approve
        self._always_allow: set[str] = set()
        self._esc_listener: EscListener | None = None
        self._sandbox = sandbox_manager
        self._plan_manager: PlanModeManager | None = None
        # Permission mode tracking (matches toolPermissionContext.mode in TS)
        self._mode: str = "default"  # 'default' | 'plan'
        self._pre_plan_mode: str | None = None
        self._pre_plan_always_allow: set[str] | None = None
        # Dream mode: restrict writes to memory directory only
        self._dream_mode: bool = False
        self._dream_memory_dir: str | None = None

    def set_plan_manager(self, plan_manager: PlanModeManager) -> None:
        self._plan_manager = plan_manager

    def enter_dream_mode(self, memory_dir: str) -> None:
        """Enable dream permission isolation — writes only within memory_dir."""
        self._dream_mode = True
        self._dream_memory_dir = os.path.realpath(memory_dir)

    def exit_dream_mode(self) -> None:
        self._dream_mode = False
        self._dream_memory_dir = None

    def set_esc_listener(self, listener: EscListener | None):
        self._esc_listener = listener

    @property
    def mode(self) -> str:
        return self._mode

    def enter_plan_mode(self) -> None:
        """Stash current permission state and switch to plan mode.

        Corresponds to prepareContextForPlanMode() in permissionSetup.ts.
        """
        self._pre_plan_mode = self._mode
        self._pre_plan_always_allow = set(self._always_allow)
        self._mode = "plan"
        # Strip dangerous always-allow rules during plan mode
        self._always_allow -= {"Bash", "Edit", "Write", "Agent"}

    def exit_plan_mode(self) -> None:
        """Restore permission state from before plan mode."""
        self._mode = self._pre_plan_mode or "default"
        self._pre_plan_mode = None
        if self._pre_plan_always_allow is not None:
            self._always_allow = self._pre_plan_always_allow
            self._pre_plan_always_allow = None

    def check(self, tool: Tool, inputs: dict) -> PermissionBehavior:
        # Dream mode: strict isolation — read-only + memory-dir writes only
        if self._dream_mode:
            return self._check_dream(tool, inputs)

        # Plan mode restrictions: only allow read-only tools + plan file writes
        if self._mode == "plan":
            return self._check_plan(tool, inputs)

        if tool.is_read_only():
            return "allow"
        if self._auto_approve:
            return "allow"
        if tool.name in self._always_allow:
            return "allow"

        # Sandbox auto-allow: sandboxed Bash commands need no confirmation
        if (
            tool.name == "Bash"
            and self._sandbox is not None
            and self._sandbox.is_auto_allow()
            and self._sandbox.should_sandbox(inputs.get("command", ""))
        ):
            return "allow"

        return self._prompt_user(tool, inputs)

    def _check_plan(self, tool: Tool, inputs: dict) -> PermissionBehavior:
        """Plan mode: read-only tools + plan file writes + agent tools."""
        if tool.name in _PLAN_MODE_ALLOWED_TOOLS:
            return "allow"
        if tool.name in _PLAN_MODE_WRITE_TOOLS:
            file_path = inputs.get("file_path", "")
            plan_path = self._plan_manager.plan_file_path if self._plan_manager else None
            if plan_path and file_path == plan_path:
                return "allow"
            from rich.console import Console
            Console().print(
                f"[yellow]Plan mode: can only edit the plan file "
                f"({plan_path})[/yellow]"
            )
            return "deny"
        from rich.console import Console
        Console().print(
            f"[yellow]Plan mode: {tool.name} is not allowed. "
            f"Only read-only tools and plan file editing are permitted.[/yellow]"
        )
        return "deny"

    def _check_dream(self, tool: Tool, inputs: dict) -> PermissionBehavior:
        """Dream mode: read-only tools + Edit/Write only within memory dir."""
        if tool.is_read_only():
            return "allow"
        if tool.name in ("Edit", "Write"):
            file_path = inputs.get("file_path", "")
            if self._dream_memory_dir and isinstance(file_path, str):
                try:
                    target = os.path.realpath(file_path)
                    common = os.path.commonpath([self._dream_memory_dir, target])
                    if common == self._dream_memory_dir:
                        return "allow"
                except ValueError:
                    pass
            return "deny"
        # Bash and everything else: denied during dream
        return "deny"

    def _prompt_user(self, tool: Tool, inputs: dict) -> PermissionBehavior:
        from rich.console import Console
        console = Console()
        console.print(f"\n[bold yellow]Permission required:[/bold yellow] [bold]{tool.name}[/bold]")
        for k, v in inputs.items():
            val = str(v)[:200] + ("..." if len(str(v)) > 200 else "")
            console.print(f"  [dim]{k}:[/dim] {val}")

        console.print("\n  Allow? \\[y]es / \\[n]o / \\[a]lways: ", end="")

        # Pause the ESC listener so it doesn't steal our keystrokes
        if self._esc_listener:
            self._esc_listener.pause()

        fd = sys.stdin.fileno()
        try:
            while True:
                # In cbreak mode: read single byte unbuffered, no Enter needed
                b = os.read(fd, 1)

                # Check for ESC — distinguish bare ESC from escape
                # sequences (arrow keys etc.) that start with \x1b
                if b == b'\x1b':
                    if select.select([fd], [], [], 0.05)[0]:
                        # Escape sequence — drain and ignore
                        while select.select([fd], [], [], 0.01)[0]:
                            os.read(fd, 64)
                        continue
                    # Genuine ESC press
                    console.print()
                    if self._esc_listener:
                        self._esc_listener.pressed = True
                    return "deny"

                choice = b.decode("utf-8", errors="ignore").lower()
                console.print(choice)  # echo the char

                if choice == 'y':
                    return "allow"
                if choice == 'n':
                    return "deny"
                if choice == 'a':
                    self._always_allow.add(tool.name)
                    return "allow"
                console.print("  Please enter y, n, or a: ", end="")
        finally:
            # Resume the ESC listener
            if self._esc_listener:
                self._esc_listener.resume()
